// Package gen is the App Store Connect API client generated by oapi-codegen
// from api/openapi.oas.json (asc.gen.go), plus the hand-written types the
// generator configuration maps to.
package gen

import (
	"encoding/json"
	"fmt"
	"time"
)

// DateTime is the Go type generated for the spec's "date-time" strings.
// App Store Connect writes them with a numeric offset that has no colon,
// e.g. "2027-01-02T03:04:05.000+0000", which time.Time's RFC 3339 decoding
// rejects.
type DateTime struct {
	time.Time
}

// dateTimeLayouts are tried in order when parsing.
var dateTimeLayouts = []string{
	"2006-01-02T15:04:05.000-0700",
	"2006-01-02T15:04:05-0700",
	time.RFC3339Nano,
}

// ParseDateTime parses a date-time in any of the forms App Store Connect
// returns.
func ParseDateTime(s string) (DateTime, error) {
	for _, layout := range dateTimeLayouts {
		if t, err := time.Parse(layout, s); err == nil {
			return DateTime{t}, nil
		}
	}
	return DateTime{}, fmt.Errorf("parsing date-time %q", s)
}

// MarshalText writes RFC 3339, which App Store Connect accepts in requests.
func (d DateTime) MarshalText() ([]byte, error) {
	return []byte(d.Format(time.RFC3339)), nil
}

// UnmarshalText parses any of the forms App Store Connect returns.
func (d *DateTime) UnmarshalText(b []byte) error {
	parsed, err := ParseDateTime(string(b))
	if err != nil {
		return err
	}
	*d = parsed
	return nil
}

// MarshalJSON writes the date-time as a JSON string.
func (d DateTime) MarshalJSON() ([]byte, error) {
	return json.Marshal(d.Format(time.RFC3339))
}

// UnmarshalJSON reads a JSON string. null leaves d unchanged, as it does
// for time.Time.
func (d *DateTime) UnmarshalJSON(b []byte) error {
	if string(b) == "null" {
		return nil
	}
	var s string
	if err := json.Unmarshal(b, &s); err != nil {
		return fmt.Errorf("date-time is not a JSON string: %w", err)
	}
	return d.UnmarshalText([]byte(s))
}
